INSERT INTO kb_chunk (id, doc_id, chunk_index, vector_id, content, create_time) VALUES
(2001, 1001, 0, 'vec-1001-chk0-a1b2c3d4e5f6', '一、退货政策总则\n\n1.1 本平台支持自签收之日起7天内无理由退货，特殊商品除外。\n1.2 退货商品须保持原包装完整、配件齐全、未经人为损坏。\n1.3 退货申请可通过在线客服或自助页面提交，审核通过后生成退货单号。', '2026-09-01 09:15:10'),
(2002, 1001, 1, 'vec-1001-chk1-b2c3d4e5f6a1', '1.4 退货运费承担规则：质量问题由卖家承担；非质量问题（如七天无理由）由买家承担，运费从退款中扣除。\n1.5 退款将在收到退货商品并验收通过后1-3个工作日内原路退回。', '2026-09-01 09:15:15'),
(2003, 1001, 2, 'vec-1001-chk2-c3d4e5f6a1b2', '1.6 以下商品不支持无理由退货：定制商品、贴身衣物、已拆封数码产品、生鲜食品。\n1.7 如对退货结果有异议，可联系人工客服进行申诉处理。', '2026-09-01 09:15:20'),
(2004, 1002, 0, 'vec-1002-chk0-d4e5f6a1b2c3', '二、七天无理由退货细则\n\n2.1 七天无理由退货期限自快递签收次日零时起算，至第七天23:59止。\n2.2 申请条件：商品完好、不影响二次销售；附上订单号和退货原因。', '2026-09-01 10:20:25'),
(2005, 1002, 1, 'vec-1002-chk1-e5f6a1b2c3d4', '2.3 退货流程：提交申请→客服审核（1个工作日内）→寄回商品→验收→退款。\n2.4 如商品存在使用痕迹影响二次销售，平台有权拒绝退货或收取折旧费。', '2026-09-01 10:20:30'),
(2006, 1003, 0, 'vec-1003-chk0-f6a1b2c3d4e5', '三、换货规则说明\n\n3.1 换货须在签收后7天内申请，仅支持同款不同规格（颜色/尺码）更换。\n3.2 换货商品须保持全新未使用状态，原包装及吊牌完整。', '2026-09-02 14:30:10'),
(2007, 1003, 1, 'vec-1003-chk1-a1b2c3d4e5f6', '3.3 换货运费：质量问题双向免运费；非质量问题买家承担来回运费。\n3.4 如换货商品缺货，可申请退款或等待补货（最长15天）。', '2026-09-02 14:30:15'),
(2008, 1004, 0, 'vec-1004-chk0-b2c3d4e5f6a1', '四、保修服务条款\n\n4.1 数码电子产品享受国家三包政策：7天退货、15天换货、1年保修。\n4.2 保修期内非人为损坏免费维修；人为损坏需付费维修。', '2026-09-02 15:46:00'),
(2009, 1004, 1, 'vec-1004-chk1-c3d4e5f6a1b2', '4.3 维修周期一般为7-15个工作日，复杂故障不超过30天。\n4.4 维修后保修期顺延30天。超过保修期可申请付费维修。', '2026-09-02 15:46:05'),
(2010, 1004, 2, 'vec-1004-chk2-d4e5f6a1b2c3', '4.5 保修不包含：进水、摔坏、私自拆机、非官方维修点维修过的商品。\n4.6 如对维修结果有异议，可在取回后3天内提出复检申请。', '2026-09-02 15:46:10'),
(2011, 1005, 0, 'vec-1005-chk0-e5f6a1b2c3d4', '五、售后时限规定\n\n5.1 退货审核：1个工作日；退货验收：签收后2个工作日；退款到账：验收通过后1-3个工作日。\n5.2 换货审核：1个工作日；换货发货：审核通过后2个工作日。', '2026-09-03 09:00:15'),
(2012, 1005, 1, 'vec-1005-chk1-f6a1b2c3d4e5', '5.3 维修周期：7-15个工作日（简单故障）/ 15-30个工作日（复杂故障）。\n5.4 投诉处理时限：一般投诉3个工作日内回复；紧急投诉24小时内响应。', '2026-09-03 09:00:20'),
(2013, 1006, 0, 'vec-1006-chk0-a1b2c3d4e5f6', '六、物流配送说明\n\n6.1 普通订单48小时内发货，大件商品预约配送时间。\n6.2 偏远地区（新疆/西藏/青海）配送时间延长3-5天，加收偏远地区运费。', '2026-09-03 11:20:10'),
(2014, 1006, 1, 'vec-1006-chk1-b2c3d4e5f6a1', '6.3 合作快递：顺丰（大件/贵重）、中通（普通）、京东物流、德邦（重货）。\n6.4 物流异常超过72小时无更新可联系客服催促。', '2026-09-03 11:20:15'),
(2015, 1007, 0, 'vec-1007-chk0-c3d4e5f6a1b2', '七、订单状态流转说明\n\n7.1 订单状态：待付款→已付款→待发货→已发货→已签收→已完成。\n7.2 待付款超时30分钟自动取消；已发货后不支持修改收货地址。', '2026-09-04 08:50:10'),
(2016, 1007, 1, 'vec-1007-chk1-d4e5f6a1b2c3', '7.3 已签收后自动确认收货期限15天，超时系统自动确认。\n7.4 确认收货后可评价，评价后订单进入已完成状态。', '2026-09-04 08:50:15'),
(2017, 1009, 0, 'vec-1009-chk0-e5f6a1b2c3d4', '九、退货运费规则\n\n9.1 质量问题退货：来回运费由卖家承担，买家先行垫付后凭单据报销。\n9.2 七天无理由退货：来回运费由买家承担，从退款中扣除寄回运费。', '2026-09-05 09:30:10'),
(2018, 1009, 1, 'vec-1009-chk1-f6a1b2c3d4e5', '9.3 运费标准：首重12元/KG，续重5元/KG；偏远地区首重20元/KG，续重10元/KG。\n9.4 大件商品退货运费按物流公司报价实报实销。', '2026-09-05 09:30:15'),
(2019, 1013, 0, 'vec-1013-chk0-a1b2c3d4e5f6', '十三、会员售后服务权益\n\n13.1 普通会员：享受7天无理由退货、标准售后时限。\n13.2 银卡会员：退货免运费（每年3次）、售后优先审核。', '2026-09-07 09:00:10'),
(2020, 1013, 1, 'vec-1013-chk1-b2c3d4e5f6a1', '13.3 金卡会员：退货免运费（每年5次）、专属客服（工作时间）、延长退货期7天。\n13.4 钻石会员：不限次数退货免运费、7×24专属客服、延长退货期15天。', '2026-09-07 09:00:15');
